// Writes a trimmed copy of the look library for the Home Assistant randomiser.
// HA fetches this file from the controller at runtime, so no generated bundle
// needs to be kept in the repo or regenerated by hand.
import { readFileSync, writeFileSync, mkdirSync } from 'node:fs';

const lib = JSON.parse(readFileSync('src/engine/library.json', 'utf8'));

const looks = lib.looks.map((l) => ({
  id: l.id,
  name: l.name,
  group: l.group,
  layers: l.layers.map((layer) => ({
    target: layer.target,
    effect: layer.effect,
    palette: layer.palette,
    colors: layer.colors,
    speed: layer.speed,
    intensity: layer.intensity,
    ...(layer.spacing ? { spacing: layer.spacing } : {}),
    ...(layer.overlayEvery ? { overlayEvery: layer.overlayEvery } : {}),
    ...(layer.reverse ? { reverse: true } : {}),
  })),
}));

const holidays = lib.holidays.map((h) => ({ id: h.id, name: h.name, emoji: h.emoji, rule: h.rule }));

// Only ship palettes that a look actually references.
const used = new Set(looks.flatMap((l) => l.layers.flatMap((layer) => layer.palette ?? [])));
const palettes = lib.palettes.filter((p) => used.has(p.wled)).map((p) => ({
  wled: p.wled,
  stops: p.stops,
  ...(p.positions ? { positions: p.positions } : {}),
}));

mkdirSync('dist', { recursive: true });
const out = JSON.stringify({ looks, holidays, palettes });
writeFileSync('dist/eaveglow-library.json', out);
console.log(`Wrote dist/eaveglow-library.json: ${looks.length} looks, ${holidays.length} holidays, ${palettes.length} palettes, ${(out.length / 1024).toFixed(0)} KB`);
